    Bug 1941552 - Fix Resource leak in mime_new(). r=BenC

    CID: 1137487

    Differential Revision: https://phabricator.services.mozilla.com/D234304

diff --git a/mailnews/mime/src/mimei.cpp b/mailnews/mime/src/mimei.cpp
index 815f4fc492b..cd9df406b3a 100644
--- a/mailnews/mime/src/mimei.cpp
+++ b/mailnews/mime/src/mimei.cpp
@@ -227,7 +227,10 @@ MimeObject* mime_new(MimeObjectClass* clazz, MimeHeaders* hdrs,
   }

   object = (MimeObject*)PR_MALLOC(size);
-  if (!object) return 0;
+  if (!object) {
+    PR_Free(hdrs);
+    return 0;
+  }

   memset(object, 0, size);
   object->clazz = clazz;
